use serde_json::{json,Value};use sha2::{Digest,Sha256};use std::{fs,path::{Path,PathBuf}};
const R:&str="/home/ubuntu/src/zopro-perf-work/parallel-readiness176";
fn r(p:impl AsRef<Path>)->PathBuf{Path::new(R).join(p)}fn read(p:impl AsRef<Path>)->Value{serde_json::from_slice(&fs::read(p).unwrap()).unwrap()}fn hash(p:impl AsRef<Path>)->String{format!("{:x}",Sha256::digest(fs::read(p).unwrap()))}
fn main(){assert_eq!(read(r("native-rest/complete-link-metadata/exit.json"))["success"],true);assert_eq!(read(r("native-rest/model-tests/exit.json"))["success"],false);let mut pins=read(r("rest-pins.json"));for(p,h)in pins.as_object().unwrap(){assert_eq!(hash(p),h.as_str().unwrap());}for f in["repair-model-link.rs","repair-model-link","model-tests.rs","probe-off.json","native-rest/complete-link-metadata/exit.json","native-rest/complete-link-metadata/stdout.log","native-rest/complete-link-metadata/stderr.log","native-rest/model-tests/command.json","native-rest/model-tests/exit.json","native-rest/model-tests/stderr.log","native-rest/model-tests/stdout.log"]{pins[r(f).display().to_string()]=json!(hash(r(f)));}let old=read(r("rest-plan.json"));let mut steps=old["steps"].as_array().unwrap()[1..].to_vec();steps[0]["driver"]=json!(r("model-tests.rs"));steps[1]["argv"][0]=json!(r("native-final/model-tests-sdk"));assert_eq!(steps.len(),4);fs::write(r("final-pins.json"),serde_json::to_vec_pretty(&pins).unwrap()).unwrap();fs::write(r("final-plan.json"),serde_json::to_vec_pretty(&json!({"version":1,"source_pins":r("final-pins.json"),"steps":steps})).unwrap()).unwrap();println!("Standalone model-test entry avoids unrelated SDK-main sha2 import; reusesall4successfulsteps/executable;4remainingsteps prepared");}
